/** i18n keys for the Open VS Code button. */
export interface OpenVscodeKey {
    /** Button label. */
    label: string;
    /** Tooltip shown on hover. */
    tooltip: string;
    /** Loading state text. */
    launching: string;
    /** Success state text. */
    opened: string;
    /** Error state text. */
    failed: string;
}
/** English dictionary. */
export declare const en: OpenVscodeKey;
/** Chinese dictionary. */
export declare const zh: OpenVscodeKey;
